head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50013";
scwin.obj = undefined;
scwin.frameId = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

scwin.form_editForm = { action: "", method: 'post', target: '' };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50013' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50013' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50013.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_61_onclick
 * @description img_61 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_61_onclick = async function(e){
    try {
        await scwin.disuse()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50013.img_61_onclick' }); }
};

/**
 * @method
 * @name img_62_onclick
 * @description img_62 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_62_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50013.img_62_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Disuse
 * @description Disuse 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Disuse = async function () {
    const sbmOptions = {
        id: "tx_fn_Disuse",
        method: "post",
        action: "/filing/updateForm.do",
        ref: "dma_DisuseReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name disuse
 * @description disuse 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.disuse = async function () {
    if (($c.util.getComponent('cal_endDd').getValue() === null ? '' : String($c.util.getComponent('cal_endDd').getValue())) === '') {
        await $c.win.alert("폐지일자를 넣어 주세요.");
        return;
    }
    $c.util.getComponent('dma_DisuseReq').set('method', "updateDisuseForm");
    scwin.form_editForm.action = "/filing/updateForm.do";
    await scwin.tx_fn_Disuse();
};
